<template>
    <view class="merchant-lead-page">
        <view v-if="!loggedIn" class="empty-card"><u-icon name="account" size="42" color="#8a9ab5" /><view class="empty-title">登录后进入商户工作台</view><view class="muted">使用您现有的会员身份，无需另设商户密码。</view><button class="primary-button" @tap="redirectLogin">使用会员身份登录</button></view>
        <template v-else>
            <view class="hero-card"><view class="eyebrow">MERCHANT WORKSPACE</view><view class="hero-top"><view><view class="hero-title">{{ merchant.name || '商户工作台' }}</view><view class="hero-subtitle">{{ merchant.region_text || regionText(merchant) || '仅展示当前会员绑定的门店' }}</view></view><view class="refresh-button" @tap="refresh"><u-icon name="reload" color="#ffffff" size="22" /></view></view><view class="hero-stats"><view><text class="stat-value">{{ stats.assigned ?? '—' }}</text><text class="stat-label">待接单</text></view><view><text class="stat-value">{{ stats.following ?? '—' }}</text><text class="stat-label">跟进中</text></view><view><text class="stat-value">{{ stats.deal_pending ?? '—' }}</text><text class="stat-label">成交待核</text></view></view></view>
            <view class="scope-note"><u-icon name="lock" color="#73849d" size="15" /><text>会员身份登录 · 仅本店数据</text><text class="text-link" @tap="subscribeNotices">订阅新派单 / 工单变更</text></view>
            <view class="main-tabs"><view v-for="item in tabs" :key="item.key" :class="['main-tab', { active: tab === item.key }]" @tap="changeTab(item.key)"><u-icon :name="item.icon" :color="tab === item.key ? '#4264ec' : '#8692a6'" size="18" /><text>{{ item.label }}</text></view></view>
            <view class="search-card"><u-search v-model="query.keyword" :placeholder="tab === 'workorders' ? '搜索客户、需求或工单号' : tab === 'inventory' ? '搜索商品型号或规格' : '搜索关联工单号'" :show-action="true" action-text="查询" @search="search" @custom="search" @clear="search" /><picker v-if="tab === 'workorders'" :range="statusOptions" range-key="label" :value="statusIndex" @change="changeStatus"><view class="status-picker"><text>{{ statusOptions[statusIndex].label }}</text><u-icon name="arrow-down" size="12" color="#8a96a9" /></view></picker></view>
            <view v-if="error" class="error-card"><view>{{ error }}</view><text class="text-link" @tap="refresh">重新加载</text></view>
            <view v-if="loading && !activeRows.length" class="loading-card"><u-loading-icon mode="circle" color="#4264ec" /><text>正在读取本店数据…</text></view>
            <template v-else-if="!error">
                <template v-if="tab === 'workorders'">
                    <view v-for="task in activeRows" :key="task.id" class="record-card" @tap="openTask(task.id)"><view class="record-head"><view class="record-title">{{ task.customer_name || task.lead?.customer_name || '客户需求' }}</view><text :class="['status-chip', `status-${task.status}`]">{{ statusLabel(task.status) }}</text></view><view class="record-subtitle">{{ task.task_no || `工单 #${task.id}` }}</view><view class="need-title">{{ [task.model || task.lead?.model, task.memory || task.lead?.memory].filter(Boolean).join(' · ') || '查看需求详情' }}</view><view class="record-line"><text>{{ (task.lead || task).requirements?.length ? '需求摘要' : '购机预算' }}</text><text>{{ demandHint(task.lead || task) }}</text></view><view class="record-subtitle">{{ progressLabel(task) }}</view><view class="record-line"><text>服务地区</text><text>{{ task.region_text || task.lead?.region_text || regionText(task.lead || task) || '未返回' }}</text></view><view class="record-foot"><text>{{ task.status === 'assigned' ? deadlineLabel(task.response_deadline, now) : dateTime(task.update_time || task.create_time) }}</text><text class="text-link">{{ task.status === 'assigned' ? '接单 / 拒单' : task.status === 'following' ? '跟进 / 提交成交' : '查看详情' }} ›</text></view></view>
                </template>
                <template v-else-if="tab === 'inventory'"><view class="info-note">库存为 ERP 同步快照，不代表确定可售；接单前请核对实物与库存。</view><view v-for="item in activeRows" :key="item.id" class="record-card"><view class="record-head"><view class="record-title">{{ item.model || item.name || '未识别型号' }}</view><text v-if="item.is_stale" class="status-chip status-deal_pending">快照已过期</text></view><view class="record-subtitle">{{ [item.memory, item.color, item.grade].filter(Boolean).join(' · ') || '规格未返回' }}</view><view class="record-line"><text>快照价格</text><text class="price">{{ item.price == null || item.price === '' ? '—' : money(item.price) }}</text></view><view class="record-line"><text>快照数量</text><text>{{ item.quantity ?? '未返回' }} · 可售待确认</text></view><view class="record-foot"><text>最近同步 {{ dateTime(item.last_sync_at) }}</text></view></view></template>
                <template v-else><view class="commission-summary"><view><text class="muted">待付固定佣金</text><text class="summary-money">{{ money(stats.commission_unpaid) }}</text></view><view><text class="muted">平台已登记收佣</text><text class="summary-money">{{ money(stats.commission_received) }}</text></view></view><view class="info-note">固定佣金由平台成交核验时填写，仅查看登记结果，不在本页自动扣款。</view><view v-for="item in activeRows" :key="item.id" class="record-card"><view class="record-head"><view class="record-title">{{ item.task_no || `工单 #${item.workorder_id}` }}</view><text :class="['status-chip', `status-${item.status}`]">{{ statusLabel(item.status) }}</text></view><view class="record-line"><text>固定佣金</text><text class="price">{{ money(item.amount) }}</text></view><view class="record-line"><text>收款凭证</text><text>{{ item.receipt_no || '尚未登记' }}</text></view><view v-if="item.refund_no" class="record-line"><text>退款凭证</text><text>{{ item.refund_no }}</text></view></view></template>
                <view v-if="!activeRows.length && !loading" class="empty-card"><u-icon :name="tab === 'workorders' ? 'order' : tab === 'inventory' ? 'bag' : 'rmb-circle'" color="#b4bece" size="40" /><view class="empty-title">{{ tab === 'workorders' ? '暂无符合条件的工单' : tab === 'inventory' ? '暂无库存快照' : '暂无佣金记录' }}</view><view class="muted">{{ tab === 'workorders' ? '平台分配的客资会出现在这里。' : tab === 'inventory' ? '请联系运营检查 ERP 配置与同步状态。' : '成交核验后可在此核对固定佣金。' }}</view></view>
                <view v-if="activeRows.length" class="loadmore" @tap="loadMore"><u-loadmore :status="loading ? 'loading' : activeRows.length < totals[tab] ? 'loadmore' : 'nomore'" loadmore-text="点击加载更多" nomore-text="没有更多记录了" /></view>
            </template>
        </template>
        <u-popup :show="taskVisible" mode="bottom" :round="18" :close-on-click-overlay="!saving" @close="closeTask"><view class="task-sheet"><view class="sheet-header"><view><view class="sheet-title">工单详情</view><view class="muted">{{ detail.task_no || `工单 #${selectedId}` }}</view></view><view @tap="closeTask"><u-icon name="close" size="20" color="#8995a9" /></view></view><scroll-view scroll-y class="sheet-body" :scroll-into-view="actionAnchor">
            <view v-if="detailLoading" class="loading-card"><u-loading-icon mode="circle" color="#4264ec" /></view><view v-else-if="detailError" class="error-card">{{ detailError }}<view class="text-link" @tap="loadTask">重试读取</view></view>
            <template v-else-if="detail.id"><view class="detail-heading"><text :class="['status-chip', `status-${detail.status}`]">{{ statusLabel(detail.status) }}</text><view v-if="detail.completion_status" class="muted">{{ completionLabels[detail.completion_status] }}</view><view v-if="detail.status === 'assigned'" class="inline-error">{{ deadlineLabel(detail.response_deadline, now) }}</view><view class="need-title">{{ [lead.model, lead.memory, lead.color, lead.grade].filter(Boolean).join(' · ') || '未填写购机需求' }}</view></view><view class="detail-fields"><view class="record-line"><text>客户称呼</text><text>{{ lead.customer_name || '未填写' }}</text></view><view class="record-line"><text>联系电话</text><text class="text-link" @tap="callCustomer">{{ lead.mobile || '未提供' }}</text></view><view class="record-subtitle">{{ progressLabel(detail) }}</view><view class="record-line"><text>服务地区</text><text>{{ lead.region_text || regionText(lead) }}</text></view><view v-if="!lead.requirements?.length" class="record-line"><text>客户预算</text><text>{{ budget(lead) }}</text></view><view class="record-line"><text>接单期限</text><text>{{ dateTime(detail.response_deadline) }}</text></view><view class="detail-note">{{ lead.remark || '客户暂无补充备注' }}</view></view>
                <RequirementDetails v-if="taskRequirements(detail).length" :items="taskRequirements(detail)" :mode="detail.demand_mode || lead.demand_mode" />
                <view v-if="detail.deal_no" class="detail-section"><view class="section-title">第 {{ detail.deal_revision || 1 }} 批最近申报</view><view class="record-line"><text>成交单号</text><text>{{ detail.deal_no }}</text></view><view class="record-line"><text>实际金额</text><text>{{ money(detail.deal_amount) }}</text></view><view class="detail-note">{{ detail.evidence || '未提供凭证说明' }}</view><view v-for="item in detail.deal_items || []" :key="item.catalog_id" class="record-line"><text>{{ item.title }}</text><text>{{ item.quantity }} 台 × {{ money(item.unit_price) }}</text></view></view>
                <view v-if="detail.deal_history?.length" class="detail-section"><view class="section-title">已核验成交批次 · 累计 {{ money(detail.total_confirmed_amount) }}</view><view v-for="batch in detail.deal_history" :key="batch.revision" class="follow-item"><view class="text-link" @tap="toggleBatch(batch.revision)">第 {{ batch.revision }} 批 · {{ batch.deal_no }} · {{ money(batch.amount) }} {{ expandedBatches.includes(batch.revision) ? '⌃' : '⌄' }}</view><template v-if="expandedBatches.includes(batch.revision)"><view v-for="item in batch.items || []" :key="item.catalog_id" class="record-line"><text>{{ item.title }}</text><text>{{ item.quantity }} 台 × {{ money(item.unit_price) }}</text></view><view class="muted">核验时间 {{ dateTime(batch.verified_at) }} · 本批固定佣金 {{ money(batch.commission_amount) }}</view><view v-if="batch.close_remaining" class="muted">剩余需求已结束：{{ batch.remaining_reason }}</view></template></view></view>
                <view class="detail-section"><view class="section-title">下一步</view><view class="button-row"><template v-if="detail.status === 'assigned'"><button class="primary-button" :disabled="saving || isExpired(detail, now)" @tap="chooseAction('accept')">确认接单</button><button class="plain-button" :disabled="saving" @tap="chooseAction('reject')">拒绝接单</button></template><template v-if="detail.status === 'following'"><button class="primary-button" :disabled="saving" @tap="chooseAction('follow')">添加跟进</button><button class="plain-button" :disabled="saving" @tap="chooseAction('deal')">提交成交</button></template><button v-if="['assigned', 'following'].includes(detail.status)" class="plain-button" :disabled="saving" @tap="chooseAction('close')">{{ Number(detail.total_confirmed_amount) > 0 ? '结束剩余需求' : '关闭工单' }}</button><button v-if="detail.status === 'deal_pending'" class="plain-button" :disabled="saving" @tap="chooseAction('deal')">修改本批申报</button><text v-if="detail.status === 'deal_pending'" class="muted">等待平台核验；修改后将使用新的申报版本。</text><text v-if="detail.status === 'completed'" class="muted">平台已确认成交；佣金以平台登记结果为准。</text><text v-if="['closed', 'rejected', 'reassigned', 'cancelled'].includes(detail.status)" class="muted">工单已结束，记录继续保留。</text></view></view>
                <view v-if="action" id="action-form" class="action-card"><view class="section-title">{{ actionTitles[action] }}</view><view v-if="action === 'accept'" class="info-note">请先确认实际库存与客户需求；接单不会自动锁货。</view><view v-if="action === 'reject'" class="info-note">拒单后客资回到待分配池，平台将重新安排。</view><template v-if="action === 'follow'"><text class="field-label">本次跟进内容 *</text><u-textarea v-model="form.content" placeholder="联系结果、到店安排及下一步" :maxlength="2000" count /></template><template v-if="action === 'deal'"><DealItemsForm v-model="saleRows" :task="detail" /><text class="field-label">本批成交单号 *</text><u-input v-model="form.deal_no" placeholder="可核对的 ERP 或销售单号" maxlength="100" /><text class="field-label">成交凭证 / 核对说明 *</text><u-textarea v-model="form.evidence" placeholder="填写凭证编号、凭证链接或可核对说明" :maxlength="2000" /><text class="field-label">补充备注</text><u-textarea v-model="form.remark" placeholder="可选" :maxlength="1000" /><view class="record-line"><text>核验后结束剩余需求</text><switch :checked="form.close_remaining" color="#4264ec" @change="form.close_remaining = $event.detail.value" /></view><template v-if="form.close_remaining"><text class="field-label">结束剩余原因 *</text><u-textarea v-model="form.remaining_reason" placeholder="说明未满足需求不再继续的原因" :maxlength="1000" /></template></template><template v-if="['reject', 'close'].includes(action)"><text class="field-label">处理原因 *</text><u-textarea v-model="form.reason" placeholder="请填写原因，平台可据此继续处理" :maxlength="1000" /></template><view v-if="actionError" class="inline-error">{{ actionError }}</view><view class="button-row" style="margin-top: 18px"><button class="plain-button" :disabled="saving" @tap="action = ''">取消</button><button class="primary-button" :loading="saving" :disabled="saving" @tap="submitAction">{{ actionTitles[action] }}</button></view></view>
                <view class="detail-section"><view class="section-title">跟进记录</view><view v-if="!detail.followups?.length" class="muted">暂无跟进记录</view><view v-for="item in detail.followups || []" :key="item.id" class="follow-item"><view class="follow-content">{{ item.content }}</view><view class="record-subtitle">{{ dateTime(item.create_time || item.create_at) }} · {{ item.operator_name || '经办人' }}</view></view></view>
            </template>
        </scroll-view><view class="sheet-footer"><button class="plain-button" :disabled="saving" @tap="closeTask">关闭详情</button></view></view></u-popup>
    </view>
</template>
<script setup lang="ts">
import { computed, nextTick, reactive, ref } from 'vue'
import { onHide, onPullDownRefresh, onReachBottom, onShow, onUnload } from '@dcloudio/uni-app'
import { getToken } from '@/utils/common'
import { useLogin } from '@/hooks/useLogin'
import RequirementDetails from './components/RequirementDetails.vue'
import DealItemsForm from './components/DealItemsForm.vue'
import { buildDealRows, completionLabels, deadlineLabel, dealItems, isExpired, progressLabel, taskRequirements, validateDeal } from '../../utils/deal'
import { useSubscribeMessage } from '@/hooks/useSubscribeMessage'
import { getMerchantTask, getMerchantWorkbench, merchantTaskAction } from '../../api'
type Row = Record<string, any>
type Tab = 'workorders' | 'inventory' | 'commissions'
type Action = '' | 'accept' | 'reject' | 'follow' | 'deal' | 'close'
const pageUrl = '/addon/hsx_lead/pages/workbench/index'
const login = useLogin(), loggedIn = ref(false), merchant = ref<Row>({}), stats = ref<Row>({}), error = ref(''), loading = ref(false)
const tab = ref<Tab>('workorders'), tabs = [{ key: 'workorders' as Tab, label: '客资工单', icon: 'order' }, { key: 'inventory' as Tab, label: '本店库存', icon: 'bag' }, { key: 'commissions' as Tab, label: '佣金记录', icon: 'rmb-circle' }]
const lists = reactive<Record<Tab, Row[]>>({ workorders: [], inventory: [], commissions: [] }), totals = reactive<Record<Tab, number>>({ workorders: 0, inventory: 0, commissions: 0 })
const activeRows = computed(() => lists[tab.value]), query = reactive({ page: 1, limit: 20, keyword: '', status: '' })
const labels: Record<string, string> = { assigned: '待接单', following: '跟进中', deal_pending: '成交待核', completed: '已成交', rejected: '已拒单', reassigned: '已转派', closed: '已关闭', cancelled: '已撤销', unpaid: '待付佣金', paid: '已登记收佣', refund_pending: '待退佣', refunded: '已退款', void: '已作废' }
const statusOptions = [{ value: '', label: '全部状态' }, ...['assigned', 'following', 'deal_pending', 'completed', 'rejected', 'closed', 'cancelled'].map(value => ({ value, label: labels[value] }))]
const statusIndex = computed(() => Math.max(0, statusOptions.findIndex(item => item.value === query.status)))
const statusLabel = (value: string) => labels[value] || value || '未设置'
const money = (value: any) => `¥${Number(value || 0).toFixed(2)}`
const budget = (row: Row) => Number(row.budget_min) > 0 && Number(row.budget_max) > 0 ? `${money(row.budget_min)} – ${money(row.budget_max)}` : Number(row.budget_max) > 0 ? `最高 ${money(row.budget_max)}` : Number(row.budget_min) > 0 ? `${money(row.budget_min)} 起` : '预算未确定'
const demandHint = (row: Row) => row.requirements?.length ? `${row.demand_mode === 'all' ? '分别要多台' : '任选一款'} · ${row.requirements.length} 款意向机型` : budget(row)
const regionText = (value: Row) => [value.province_name, value.city_name, value.district_name].filter(Boolean).join(' / ')
const dateTime = (value: any) => { if (!value) return '尚未记录'; const date = new Date(/^\d+$/.test(String(value)) ? Number(value) * 1000 : value); return `${date.getFullYear()}/${String(date.getMonth() + 1).padStart(2, '0')}/${String(date.getDate()).padStart(2, '0')} ${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}` }
const message = (cause: any, fallback: string) => String(cause?.msg || cause?.message || cause?.errMsg || fallback)
function redirectLogin() { login.setLoginBack({ url: pageUrl, mode: 'redirectTo' }) }
let sequence = 0, disposed = false, lastIdentity = ''
async function load(append = false) {
    if (!getToken()) { loggedIn.value = false; return }
    const token = ++sequence, currentTab = tab.value, nextPage = append ? query.page + 1 : 1
    loading.value = true; error.value = ''
    try {
        const response: any = await getMerchantWorkbench({ ...query, page: nextPage, tab: currentTab })
        if (token !== sequence || disposed) return
        const data = response.data || {}; merchant.value = data.merchant || {}; stats.value = data.stats || {}
        for (const key of ['workorders', 'inventory', 'commissions'] as Tab[]) {
            const source = data[key] || {}, rows = Array.isArray(source) ? source : source.data || []
            if (!append || key === currentTab) { lists[key] = append ? [...lists[key], ...rows.filter((row: Row) => !lists[key].some(item => item.id === row.id))] : rows; totals[key] = Number(source.total ?? rows.length) }
        }
        query.page = nextPage
    } catch (cause) { if (token === sequence && !disposed) error.value = message(cause, '读取失败，请检查会员是否已绑定门店并重试。') }
    finally { if (token === sequence && !disposed) loading.value = false }
}
async function refresh() { await load(false) }
function search() { void load(false) }
function changeTab(value: Tab) { if (tab.value === value) return; tab.value = value; query.status = ''; query.keyword = ''; void load(false) }
function changeStatus(event: any) { query.status = statusOptions[Number(event.detail.value)]?.value || ''; void load(false) }
function loadMore() { if (!loading.value && activeRows.value.length < totals[tab.value]) void load(true) }
const taskVisible = ref(false), detailLoading = ref(false), detailError = ref(''), selectedId = ref(0), detail = ref<Row>({}), action = ref<Action>(''), saving = ref(false), actionError = ref(''), actionAnchor = ref('')
const lead = computed(() => detail.value.lead || detail.value)
const saleRows = ref<Row[]>([]), expandedBatches = ref<number[]>([]), now = ref(Date.now())
let clock: ReturnType<typeof setInterval> | undefined
function startClock() { if (clock) clearInterval(clock); now.value = Date.now(); clock = setInterval(() => { now.value = Date.now() }, 30000) }
function stopClock() { if (clock) clearInterval(clock); clock = undefined }
function toggleBatch(value: number) { expandedBatches.value = expandedBatches.value.includes(value) ? expandedBatches.value.filter(item => item !== value) : [...expandedBatches.value, value] }
function subscribeNotices() {
    // #ifdef MP-WEIXIN
    useSubscribeMessage().request('hsx_lead_task_assigned,hsx_lead_task_changed')
    // #endif
    // #ifndef MP-WEIXIN
    uni.showToast({ title: '请在微信小程序内点击订阅，结果以微信授权为准', icon: 'none' })
    // #endif
}
const actionTitles: Record<string, string> = { accept: '确认接单', reject: '确认拒单', follow: '保存跟进', deal: '提交成交核验', close: '确认关闭工单' }
const form = reactive({ content: '', deal_no: '', close_remaining: false, remaining_reason: '', evidence: '', remark: '', reason: '' })
let detailSequence = 0
async function openTask(id: number) { selectedId.value = Number(id); taskVisible.value = true; detail.value = {}; action.value = ''; await loadTask() }
async function loadTask() { const token = ++detailSequence; detailLoading.value = true; detailError.value = ''; try { const response: any = await getMerchantTask(selectedId.value); if (token === detailSequence && taskVisible.value) detail.value = response.data || {} } catch (cause) { if (token === detailSequence) detailError.value = message(cause, '工单读取失败，可能已无权访问。') } finally { if (token === detailSequence) detailLoading.value = false } }
function closeTask() { if (saving.value) return; taskVisible.value = false; detailSequence++; detailLoading.value = false; action.value = ''; actionError.value = '' }
async function chooseAction(value: Action) { if (value === 'accept' && isExpired(detail.value, now.value)) return; saleRows.value = buildDealRows(detail.value); action.value = value; actionError.value = ''; Object.assign(form, { content: '', deal_no: '', close_remaining: false, remaining_reason: '', evidence: '', remark: '', reason: '' }); if (value === 'deal' && detail.value.status === 'deal_pending') Object.assign(form, { deal_no: detail.value.deal_no || '', evidence: detail.value.evidence || '', close_remaining: !!detail.value.close_remaining, remaining_reason: detail.value.remaining_reason || '' }); actionAnchor.value = ''; await nextTick(); actionAnchor.value = 'action-form' }
function callCustomer() { if (lead.value.mobile) uni.makePhoneCall({ phoneNumber: String(lead.value.mobile), fail: () => uni.showToast({ title: '未能拨打，请手动联系客户', icon: 'none' }) }) }
async function submitAction() {
    if (!action.value || saving.value) return
    actionError.value = ''
    if (action.value === 'follow' && !form.content.trim()) { actionError.value = '请填写本次跟进内容'; return }
    if (['reject', 'close'].includes(action.value) && !form.reason.trim()) { actionError.value = '请填写处理原因'; return }
    if (action.value === 'deal') { if (!form.deal_no.trim() || !form.evidence.trim()) { actionError.value = '请填写本批成交单号与可核对的凭证说明'; return }; const issue = validateDeal(detail.value, saleRows.value, form.close_remaining, form.remaining_reason); if (issue) { actionError.value = issue; return } }
    saving.value = true
    const current = action.value
